import os
from fastapi import FastAPI, Request, HTTPException, status
from fastapi.responses import JSONResponse
import uvicorn
from scalekit import ScalekitClient

app = FastAPI()

scalekit_client = ScalekitClient(
    env_url=os.environ.get("SCALEKIT_ENVIRONMENT_URL", "https://example.scalekit.com"),
    client_id=os.environ.get("SCALEKIT_CLIENT_ID", "default_client_id"),
    client_secret=os.environ.get("SCALEKIT_CLIENT_SECRET", "default_client_secret")
)

@app.middleware("http")
async def auth_middleware(request: Request, call_next):
    if request.url.path == "/.well-known/oauth-protected-resource":
        return await call_next(request)

    auth_header = request.headers.get("Authorization")
    if not auth_header or not auth_header.startswith("Bearer "):
        return JSONResponse(status_code=401, content={"detail": "Missing or invalid Bearer token"})

    token = auth_header.split(" ")[1]

    try:
        token_data = scalekit_client.validate_token(token)
        request.state.token_data = token_data
    except Exception as e:
        return JSONResponse(status_code=401, content={"detail": "Invalid token"})

    response = await call_next(request)
    return response

@app.get("/.well-known/oauth-protected-resource")
async def oauth_protected_resource():
    env_url = os.environ.get("SCALEKIT_ENVIRONMENT_URL", "")
    return {
        "authorization_servers": [f"{env_url}/resources/res_123"],
        "bearer_methods_supported": ["header"],
        "resource": "https://mcp.example.com",
        "scopes_supported": ["todo:read", "todo:write"]
    }

@app.post("/tools/execute")
async def execute_tool(request: Request):
    token_data = request.state.token_data
    scopes = token_data.get("scope", "")
    if not scopes:
        scopes = token_data.get("scopes", [])
    if isinstance(scopes, str):
        scopes = scopes.split()

    if "todo:write" not in scopes:
        raise HTTPException(status_code=403, detail="Insufficient scope")

    return {"status": "success"}

if __name__ == "__main__":
    uvicorn.run(app, host="0.0.0.0", port=8080)

